import torch
import numpy as np

# Create test images with potential triggers in different corners
base_img = x_clean[0:1].clone()

def add_patch(img, corner, pattern_type='white', size=3):
    img = img.clone()
    # img shape: (3, 32, 32)
    c = img.shape[0]
    h = img.shape[1]
    w = img.shape[2]

    if corner == 'tl':
        r_start, c_start = 1, 1
    elif corner == 'tr':
        r_start, c_start = 1, w - size - 1
    elif corner == 'bl':
        r_start, c_start = h - size - 1, 1
    elif corner == 'br':
        r_start, c_start = h - size - 1, w - size - 1

    if pattern_type == 'white':
        patch_val = 255
        img[:, r_start:r_start+size, c_start:c_start+size] = patch_val
    elif pattern_type == 'checkerboard':
        for i in range(size):
            for j in range(size):
                val = 255 if (i + j) % 2 == 0 else 0
                img[:, r_start+i, c_start+j] = val
    elif pattern_type == 'random':
        for i in range(size):
            for j in range(size):
                val = 255 if np.random.rand() > 0.5 else 0
                img[:, r_start+i, c_start+j] = val
    return img

